"""Local, read-only event viewer. No model, reference answers, or remote assets."""
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse, parse_qs
from .events import read_events

HTML = r'''<!doctype html><html><meta charset="utf-8"><title>Joint token-and-memory trajectories</title>
<style>body{font:15px system-ui;background:#101820;color:#eee;margin:24px}button,select,input{padding:7px;margin:5px}pre{white-space:pre-wrap;overflow-wrap:anywhere}#cards{display:grid;grid-template-columns:repeat(4,minmax(220px,1fr));gap:12px}.card,section{background:#1d2934;padding:15px;border-radius:8px;margin-bottom:15px}.active{border:2px solid #65d7b1}.new{color:#65d7b1}.revised{color:#ffbd69}.small{color:#b2beca;font-size:13px}@media(max-width:1000px){#cards{grid-template-columns:repeat(2,1fr)}}</style>
<h1>Joint token-and-memory trajectories</h1><p>Sequential execution • numerical memory diagnostics are not readable thoughts • intermediate text is provisional.</p>
<p>Cancellation via dashboard: unsupported. Stop the runner with Ctrl-C; saved boundaries can be resumed.</p>
<button id="live">Live</button><button id="play">Replay</button><button id="pause">Pause</button><input id="timeline" type="range" min="0" value="0" style="width:45%"><span id="position"></span>
<p><label>Question: <select id="promptfilter"></select></label><label>Condition / memory scale: <select id="scalefilter"></select></label></p><section id="meta"></section><section id="shared"></section><div id="cards"></div><section><h3>Independent sampling / verification</h3><select id="other"></select><pre id="othertext"></pre></section><section><h3>Boundary diversity diagnostics</h3><pre id="diversity"></pre></section><section><h3>Errors and grading status</h3><pre id="errors"></pre></section>
<script>
let events=[],mode='live',cursor=0,choices={},renderedOnce=false;const $=id=>document.getElementById(id);function txt(el,s){el.textContent=s??''}
function render(){let subset=events.slice(0,cursor),states={},last={},div=[],errors=[],meta={};for(const e of subset){if(e.event==='run_metadata')meta=e;if(e.event==='branch_diversity')div.push(e);if(e.event.includes('failed')||e.event.includes('error')||e.event==='grading_status')errors.push(e);if(e.trajectory_id){last[e.trajectory_id]={...(last[e.trajectory_id]||{}),...e};if(e.event==='trajectory_initial')states[e.trajectory_id]=e.token_ids.slice();if(e.changes)for(const c of e.changes)states[e.trajectory_id][c.position]=c.new_id;}}
function filterOptions(id,values){let el=$(id),previous=el.value;el.replaceChildren();for(const v of values){let o=document.createElement('option');o.value=v;o.textContent=v;el.append(o)}if(values.includes(previous))el.value=previous;el.onchange=()=>{choices={};render()};return el.value}let promptValues=[...new Set(Object.values(last).map(e=>e.prompt_id).filter(Boolean))];let selectedPrompt=filterOptions('promptfilter',promptValues);let scaleValues=[...new Set(Object.values(last).filter(e=>!selectedPrompt||e.prompt_id===selectedPrompt).map(e=>e.sweep_epsilon===undefined?'single run':String(e.sweep_epsilon)))];let selectedScale=filterOptions('scalefilter',scaleValues);let visible=Object.values(last).filter(e=>(!selectedPrompt||e.prompt_id===selectedPrompt)&&(!selectedScale||(e.sweep_epsilon===undefined?'single run':String(e.sweep_epsilon))===selectedScale));let active=Object.values(last).filter(e=>e.status==='generating').map(e=>e.trajectory_id);txt($('meta'),JSON.stringify({run:meta.run_id,configuration:meta.configuration,events:cursor,total_received:events.length,active,backbone_calls:subset.reduce((m,e)=>Math.max(m,e.actual_backbone_calls||0),0)},null,2));$('meta').style.whiteSpace='pre-wrap';$('shared').replaceChildren();for(const e of visible.filter(e=>e.phase==='shared')){let h=document.createElement('h3');txt(h,e.prompt_id+' / '+e.condition);let p=document.createElement('pre');txt(p,e.prompt);let g=document.createElement('pre');txt(g,e.generated_text);let d=document.createElement('pre');txt(d,JSON.stringify({boundary:e.completed_steps,memory_source_token_version:e.memory_source_token_version,token_version:e.token_version,status:e.status},null,2));$('shared').append(h,p,g,d)}
$('cards').replaceChildren();for(let c=0;c<4;c++){let card=document.createElement('div');card.className='card';let h=document.createElement('h3');txt(h,'Candidate '+c);card.append(h);let options=visible.filter(e=>e.candidate_id===c);let sel=document.createElement('select');for(const e of options){let o=document.createElement('option');o.value=e.trajectory_id;o.textContent=(e.mode||e.phase)+' / rollout '+(e.rollout_id??'—')+' / '+e.status;sel.append(o)}if(options.some(e=>e.trajectory_id===choices[c]))sel.value=choices[c];sel.onchange=()=>{choices[c]=sel.value;render()};card.append(sel);let e=last[sel.value];if(e){choices[c]=sel.value;if(e.status==='generating')card.classList.add('active');let pre=document.createElement('pre');txt(pre,(e.status==='completed'&&e.raw_response)?e.raw_response:(e.generated_text||e.raw_response||'Queued'));card.append(pre);let changes=document.createElement('p');changes.className='new';txt(changes,'Newly revealed: '+(e.changes||[]).filter(x=>x.kind==='revealed').map(x=>x.new_text).join(' | '));let revisions=document.createElement('p');revisions.className='revised';txt(revisions,'Revised: '+(e.changes||[]).filter(x=>x.kind==='revised').map(x=>x.new_text).join(' | '));card.append(changes,revisions);let details=document.createElement('pre');txt(details,JSON.stringify({prompt_id:e.prompt_id,memory_scale:e.sweep_epsilon??e.epsilon,status:e.status,seed:e.seed,rollout_seed:e.rollout_seed,block:e.block,iteration:e.iteration_in_block,remaining_masks:e.remaining_masks,remaining_budget:e.remaining_budget,backbone_calls:e.actual_backbone_calls,elapsed_seconds:e.elapsed_seconds,gpu_allocated_bytes:e.gpu_allocated_bytes,gpu_peak_bytes:e.gpu_peak_bytes,diagnostics:e.diagnostics,token_version:e.token_version,memory_source_token_version:e.memory_source_token_version,final_answer:e.extracted_final_answer,correctness:e.correctness||'NOT_GRADED',endorsement:e.false_belief_endorsement||'NOT_GRADED'},null,2));card.append(details)}$('cards').append(card)}
let prev=$('other').value;$('other').replaceChildren();for(const e of visible.filter(e=>e.candidate_id===undefined&&e.phase!=='shared')){let o=document.createElement('option');o.value=e.trajectory_id;txt(o,e.trajectory_id+' / '+e.status);$('other').append(o)}if(last[prev])$('other').value=prev;let other=last[$('other').value];txt($('othertext'),other?JSON.stringify(other,null,2):'');$('other').onchange=render;txt($('diversity'),JSON.stringify(div,null,2));txt($('errors'),errors.length?JSON.stringify(errors,null,2):'No recorded errors. Semantic correctness and endorsement grading have not run.');$('timeline').max=events.length;$('timeline').value=cursor;txt($('position'),cursor+' / '+events.length)}
$('live').onclick=()=>{mode='live';cursor=events.length;render()};$('pause').onclick=()=>mode='pause';$('play').onclick=()=>{mode='replay';cursor=0};$('timeline').oninput=e=>{mode='pause';cursor=Number(e.target.value);render()};async function poll(){try{let r=await fetch('/api/events?after='+(events.length?events.at(-1).sequence:0));let incoming=await r.json(),previousCursor=cursor;events.push(...incoming);if(mode==='live')cursor=events.length;if(mode==='replay')cursor=Math.min(events.length,cursor+1);if(incoming.length||cursor!==previousCursor||!renderedOnce){render();renderedOnce=true}}catch(e){txt($('errors'),'Event fetch error: '+e)}setTimeout(poll,700)}poll();
</script></html>'''

def serve(directory,host='127.0.0.1',port=8765):
    directory=Path(directory).resolve()
    class Handler(BaseHTTPRequestHandler):
        def do_GET(self):
            url=urlparse(self.path)
            if url.path=='/':data=HTML.encode();mime='text/html; charset=utf-8'
            elif url.path=='/api/events':
                try:after=int(parse_qs(url.query).get('after',['0'])[0])
                except ValueError:self.send_error(400);return
                data=json.dumps([e for e in read_events(directory/'events.jsonl') if e['sequence']>after],ensure_ascii=False).encode();mime='application/json'
            else:self.send_error(404);return
            self.send_response(200);self.send_header('Content-Type',mime);self.send_header('Content-Length',str(len(data)));self.send_header('Cache-Control','no-store');self.end_headers();self.wfile.write(data)
        def log_message(self,*args):pass
    server=ThreadingHTTPServer((host,port),Handler)
    print(f'Local dashboard/replay: http://{host}:{server.server_port} / {directory}',flush=True)
    try:server.serve_forever()
    except KeyboardInterrupt:pass
    finally:server.server_close()
